<script setup lang="ts">
defineOptions({ name: 'OperationsPage' });
import { Head, Link } from '@inertiajs/vue3';
import { onUnmounted, ref } from 'vue';
import { dateUTC, statusLabel } from '@/types/leaderboard';
import type { OwnRun, PageSlice } from '@/types/leaderboard';
defineProps<{ runs: PageSlice<OwnRun & { nickname: string }>; filter: string; counts: Record<string, number>; payment_failures: { id: string; provider: string; status: string; fulfillment_status: string; verification_error: string | null; created_at: string }[] }>();
const health = ref<Record<string, unknown> | null>(null), error = ref(''), busy = ref(false), controller = new AbortController();
onUnmounted(() => controller.abort());
async function diagnose() {
    if (busy.value) return; busy.value = true; error.value = '';
    try { const response = await fetch('/api/v1/operations/health', { credentials: 'same-origin', headers: { Accept: 'application/json' }, signal: AbortSignal.any([controller.signal, AbortSignal.timeout(20000)]) }); if (!response.ok) throw new Error(response.status === 429 ? 'Diagnostics are available twice per minute.' : 'Could not retrieve diagnostics.'); health.value = await response.json(); }
    catch (failure) { if (!controller.signal.aborted) error.value = failure instanceof Error ? failure.message : 'No connection.'; }
    finally { busy.value = false; }
}
</script>
<template><Head title="Operations" /><section class="site-section leaderboard-page operations-page"><p class="overline">PRIVATE OPERATOR PANEL</p><h1>Operations</h1><div class="rank-stats"><article v-for="(value, label) in counts" :key="label"><small>{{ label }}</small><strong>{{ value }}</strong></article></div><nav class="operations-nav" aria-label="Result filter"><Link v-for="status in ['pending_review', 'accepted', 'rejected', 'active']" :key="status" :href="`/operations?status=${status}`" :aria-current="filter === status ? 'page' : undefined">{{ statusLabel[status] }}</Link><Link href="/operations/users">Users</Link><Link href="/leaderboard">Leaderboard Entries →</Link></nav><h2>Game Runs · {{ statusLabel[filter] }}</h2><div v-if="runs.data.length" class="progress-table-wrap"><table class="progress-table"><thead><tr><th>Player</th><th>Character / mode</th><th>Score / status</th><th>Date</th></tr></thead><tbody><tr v-for="run in runs.data" :key="run.id"><td><Link :href="`/operations/runs/${run.id}`">{{ run.nickname ?? 'Profile not created' }} →</Link></td><td>{{ run.character_id }}<small>{{ run.mode }}</small></td><td>{{ run.record?.score ?? '—' }}<small>{{ statusLabel[run.status] }}</small></td><td>{{ dateUTC(run.finished_at ?? run.started_at) }}</td></tr></tbody></table></div><p v-else>No results with this status.</p><nav v-if="runs.last_page > 1" class="commerce-pagination" aria-label="Review queue"><Link v-if="runs.current_page > 1" :href="`/operations?status=${filter}&page=${runs.current_page - 1}`">← Back</Link><span>{{ runs.current_page }} / {{ runs.last_page }}</span><Link v-if="runs.current_page < runs.last_page" :href="`/operations?status=${filter}&page=${runs.current_page + 1}`">Next →</Link></nav><h2>Operational Health</h2><p>This check reads data without making changes. Worker availability requires separate monitoring.</p><button class="site-button" :disabled="busy" @click="diagnose">{{ busy ? 'Checking…' : 'Run diagnostics' }}</button><p v-if="error" role="alert" class="field-error">{{ error }}</p><pre v-if="health" data-testid="operations-health">{{ JSON.stringify(health, null, 2) }}</pre><h2>Payment Failures</h2><p v-if="!payment_failures.length">No verification or credit fulfillment errors.</p><ul v-else class="review-history"><li v-for="payment in payment_failures" :key="payment.id"><strong>{{ payment.id }}</strong><p>{{ payment.provider }} · {{ payment.status }} · {{ payment.fulfillment_status }} · {{ payment.verification_error ?? '—' }}</p><small>{{ dateUTC(payment.created_at) }}</small></li></ul><p class="notice">Recovery uses audited Artisan commands. This panel does not edit Score, balances or payment status.</p></section></template>
